function [lambda_max] = max_magnetic_latitude(i)
%MAX_MAGNETIC_LATITUDE  The highest magnetic latitude an orbit of inclination i reaches: min(90 deg, i' + tilt),
%   i' = min(i, 180 deg - i).
%   i: real[deg] (passed a plain number)
%   returns lambda_max: real[rad] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    lambda_max = 0;
    [b0, tilt] = asils.physics.env.dipole();
    ip = asils.pc.fmin(i, (3.141592653589793 - i));
    lambda_max = asils.pc.fmin(1.5707963267948966, (ip + tilt));
end
